void Solver::rephase() {
    rephases = 0;

    // Dynamically adjust threshold based on recent search progress
    if (conflicts > 0) {
        double recent_activity = (double)trail.size() / (double)conflicts;
        threshold = (int)(threshold * (0.85 + 0.05 * recent_activity));
    } else {
        threshold = (int)(threshold * 0.9);
    }

    // Increase rephase_limit more aggressively early, then stabilize
    if (rephase_limit < 32768) {
        rephase_limit += 8192;
    } else {
        rephase_limit += 4096;
    }

    // Update local_best based on current trail assignments
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            local_best[i] = value[i];
        }
    }
}
